let language:Language='zh-CN';
export function setLanguage(value:Language){language=value;}
export function t(key:string,...values:unknown[]):string {
  return (language==='en-US'?english[key]??key:key).replace(/\{(\d+)\}/g,(_,i)=>String(values[Number(i)]??''));
}
const escape=(s:string)=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const patterns=Object.keys(english).filter(key=>/\{\d+\}/.test(key)).map(key=>({key,regex:new RegExp('^'+key.split(/\{\d+\}/).map(escape).join('(.*?)')+'$','s')}));
// Domain errors keep their original messages in diagnostic records. Only the UI
// translates known messages; backend and Photoshop-provided text stays verbatim.
export function errorText(text:string):string {
  if(language==='zh-CN')return text;
  if(english[text])return english[text];
  for(const {key,regex} of patterns){const match=regex.exec(text);if(match)return t(key,...match.slice(1));}
  return text;
}
